int totalLoot(Stack<int>& loot) {
    int total = 0;
    Stack<int> temporary;
    while (!loot.isEmpty()) {
        int value = loot.pop();
        total += value;
        temporary.push(value);
    }
    // Second reversal restores the original loot stack.
    while (!temporary.isEmpty()) loot.push(temporary.pop());
    return total;
}

